@Test fun changingDailyTimePersistsAndSurvivesReopen() {
    tap("Проверка времени")
    tap("Ежедневно")
    tap("Изменить время")
    awaitText("14")
    // Hit the visible hour-up arrow, relative to the actual rendered hour bounds.
    // This exercises touch delivery through the PDF canvas rather than invoking callbacks.
    val hour = compose.onNodeWithText("14").fetchSemanticsNode().boundsInRoot
    compose.onRoot().performTouchInput {
        click(Offset(hour.right + hour.width * 0.22f, hour.center.y))
    }
    tap("Сохранить")
    compose.waitUntil(15_000) { storedTime() == "917" }
    tapHome()
    tap("Проверка времени")
    tap("Ежедневно")
    tap("Изменить время")
    compose.onNodeWithText("15").assertExists()
    Assert.assertEquals("917", storedTime())
}
private fun tapHome() {
    compose.onNodeWithContentDescription("На главную").performTouchInput { click() }
    awaitText("Проверка времени")
}
private fun keyboardVisible(): Boolean {
    var visible = false
    scenario?.onActivity {
        visible = ViewCompat.getRootWindowInsets(it.window.decorView)
            ?.isVisible(WindowInsetsCompat.Type.ime()) == true
    }
    return visible
}

