@Test fun overlayTapOpensFullOverLauncherAndCloseAcknowledges() {
    shell("appops set ${app.packageName} SYSTEM_ALERT_WINDOW allow")
    main();device.pressHome()
    val id=runBlocking { service.createOneShot("Нажатие на всплывающую карточку",System.currentTimeMillis()+15_000) }
    val e=runBlocking { dao.eventsForReminder(id).single().id }
    val card=By.descContains("Незабудка. Напоминание:")
    Assert.assertTrue("Overlay visible over launcher",device.wait(Until.hasObject(card),20_000))
    // Exclude the recent-foreground/just-delivered grace period: the visible overlay
    // must be sufficient even when the user does not react immediately.
    android.os.SystemClock.sleep(12_000)
    val bounds=device.findObject(card).visibleBounds
    device.click(bounds.centerX(),bounds.centerY())
    text("Напомнить снова")
    Assert.assertTrue("Actual overlay tap launches full Activity",resumed(FinalAlarmActivity::class.java))
    Assert.assertEquals(EventState.FIRING,event(e)?.state)
    Assert.assertTrue("Accessible full-screen close",device.wait(Until.hasObject(By.desc("Закрыть")),10_000))
    device.findObject(By.desc("Закрыть")).click()
    await("overlay-to-full close acknowledged and removed") {
        event(e)?.state==EventState.ACKNOWLEDGED && reminder(id)?.state==ReminderState.DELETED
    }
    Assert.assertFalse(FinalAlarmSignalPlayer.isActive(e))
}

