@Test fun sevenStagesUsePersistedAnchorAndFinalCompletionMarksMissed() {
    main()
    val (_,e)=seed(state=EventState.SCHEDULED,due=System.currentTimeMillis()-100)
    runBlocking { service.onAlarmSignal(e) }
    for(stage in 1..6) {
        // Controlled persisted clock fixture: no production interval is shortened.
        val now=System.currentTimeMillis()
        runBlocking {
            val previous=dao.event(e)!!
            dao.updateEvent(previous.copy(dueAt=now-FinalAlarmPolicy.offsetsMinutes[stage]*60_000,nextSignalAt=now-1))
            service.onAlarmSignal(e)
        }
        Assert.assertEquals(stage,event(e)?.retryIndex)
    }
    await("last signal completes",40_000) { event(e)?.state == EventState.MISSED }
    await("unanswered chain closes alarm windows") {
        !resumed(FinalCompactAlarmActivity::class.java) && !resumed(FinalAlarmActivity::class.java)
    }
    Assert.assertFalse(FinalAlarmSignalPlayer.isActive(e))
}

