@Test fun selectedPastClockCannotBeSavedAndNewFutureSnoozeUpdatesStoredSchedule() {
    val (id,e)=seed(due=System.currentTimeMillis())
    full(e);tap("Напомнить снова");tap("+другое")
    // Reproduce a same-hour past-minute edit (the original tests only used default 00:00).
    val localNow=Instant.ofEpochMilli(event(e)!!.dueAt).atZone(ZoneId.systemDefault())
    val s=ui.onRoot().fetchSemanticsNode().boundsInRoot.width/1080f
    if(localNow.minute>0) {
        val b=ui.onAllNodesWithText("%02d".format(localNow.minute)).onLast().fetchSemanticsNode().boundsInRoot
        ui.onRoot().performTouchInput { click(Offset(b.center.x-122*s,b.center.y)) }
    } else if(localNow.hour>0) {
        val b=ui.onAllNodesWithText("%02d".format(localNow.hour)).onFirst().fetchSemanticsNode().boundsInRoot
        ui.onRoot().performTouchInput { click(Offset(b.center.x-122*s,b.center.y)) }
    }
    closeAlarm();text("Выберите будущее время!")
    Assert.assertEquals(EventState.FIRING,event(e)?.state)
    val due=System.currentTimeMillis()+10*60_000
    runBlocking { FinalSnoozeRuntime(app).snoozeAt(e,due) }
    val local=Instant.ofEpochMilli(due).atZone(ZoneId.systemDefault())
    val slot=runBlocking { dao.scheduleSlots(id).single() }
    Assert.assertEquals(local.hour*60+local.minute,slot.minuteOfDay)
    Assert.assertEquals(local.toLocalDate().toEpochDay(),slot.epochDay)
    Assert.assertEquals(FinalAlarmRecoveryPolicy.logicalSlot(due),event(e)?.logicalSlot)
    Assert.assertEquals(EventState.SCHEDULED,event(e)?.state)
}

